(()=>{const tradeOptions=window.TradesTaxonomy?.trades||[],cityOptions=['Arlington, TX','Austin, TX','Columbus, OH','Dallas, TX','Fort Worth, TX','Frisco, TX','Garland, TX','Houston, TX','Irving, TX','McKinney, TX','Plano, TX','San Antonio, TX'];function closeMenus(except){document.querySelectorAll('.trades-suggestion-menu.open').forEach(menu=>{if(menu!==except)menu.classList.remove('open')})}function setup(input,options,onSelect){if(!input||input.dataset.themedSuggestions)return;input.dataset.themedSuggestions='true';input.removeAttribute('list');const wrap=document.createElement('div');wrap.className='trades-suggestion-wrap';input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);const menu=document.createElement('div');menu.className='trades-suggestion-menu';menu.setAttribute('role','listbox');wrap.appendChild(menu);function render(){const query=input.value.trim().toLowerCase(),matches=options.filter(value=>!query||value.toLowerCase().includes(query)).slice(0,8);menu.innerHTML=matches.length?matches.map(value=>`<button type="button" role="option" data-value="${value.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><span>${value}</span><small>Select</small></button>`).join(''):'<p>No matching options</p>';menu.classList.add('open');closeMenus(menu);menu.querySelectorAll('button').forEach(button=>button.addEventListener('mousedown',event=>{event.preventDefault();input.value=button.dataset.value;menu.classList.remove('open');onSelect?.(button.dataset.value);input.dispatchEvent(new Event('change',{bubbles:true}))}))}input.addEventListener('focus',render);input.addEventListener('input',render);input.addEventListener('keydown',event=>{if(event.key==='Escape')menu.classList.remove('open')});input.addEventListener('blur',()=>setTimeout(()=>menu.classList.remove('open'),120))}function setupAccount(){const form=document.getElementById('signupForm');if(!form)return;const city=form.querySelector('[name="city"]'),trade=form.querySelector('[data-trade-add]');setup(city,cityOptions,value=>{const parts=value.split(',').map(x=>x.trim()),state=form.querySelector('[name="state"]');city.value=parts[0];if(state)state.value=parts[1]||''});setup(trade,tradeOptions)}setupAccount();document.addEventListener('click',event=>{if(!event.target.closest('.trades-suggestion-wrap'))closeMenus()})})();
